1250	\begin{proof}
1251		\leanok
1252		\uses{def:cl-func, lem:cl-func-prod-same-level}
1253		Since an $\ell$-level CL function is also $k$-level conditionally linear for all $k \ge \ell$, it suffices to prove the claim when $\ell_j = \ell$ for all $j$. Proceed by induction on $\ell$. For $\ell = 0$ every $L^{(j)}$ is the zero function on $V^{(j)}$, so $L$ is the zero function on $V$, which is the unique $0$-level CL function on $V$ (Definition~\ref{def:cl-func}). For the inductive step with $\ell \ge 1$, decompose each $L^{(j)}$ into its first-level linear part $L^{(j)}_1$ on $V^{(j)}_1$ and its family of $(\ell-1)$-level remainders $L^{(j)}_{>1,\,v_j}$ on $V^{(j)}_{>1}$. The direct sums of the first-level parts define a linear map on $V_1 = \bigoplus_j V^{(j)}_1$, and, for each prefix value $v = \sum_j v_j$, the direct sums of the remainders are $(\ell-1)$-level conditionally linear on $V_{>1} = \bigoplus_j V^{(j)}_{>1}$ by the induction hypothesis. This exhibits $L$ in the form required by Definition~\ref{def:cl-func}.
1254	\end{proof}
1255	
1256	\begin{lemma}[Direct sums give product distributions]\label{lem:cl-dist-prod}
1257		\lean{MIPStarRE.QPBT.clDistribution_directSum_eq_prod}
1258		\leanok
1259		\uses{def:cl-dist, lem:cl-func-prod}
1260		For each $i \in \{1, \dots, m\}$ let $L^{(i)}, R^{(i)} \colon V^{(i)} \to V^{(i)}$ be $\ell_i$-level conditionally linear functions, and let $L, R \colon V \to V$ be the direct sums $L = \bigoplus_i L^{(i)}$ and $R = \bigoplus_i R^{(i)}$, as defined in Lemma~\ref{lem:cl-func-prod}. Then the conditionally linear distribution $\mu_{L,R}$ is the product distribution $\prod_{i=1}^m \mu_{L^{(i)},\,R^{(i)}}$ over $V \times V$.
1261	\end{lemma}
1262	\begin{proof}
1263		\leanok
1264		\uses{lem:cl-supported-vanishing, lem:cl-supported-restriction, lem:cl-restriction-sum}
1265		A uniformly random $x \in V$ has independent components $x^{(i)}$, each uniformly distributed in $V^{(i)}$. Hence the pair $(L(x), R(x)) = \bigl( (L^{(i)}(x^{(i)}))_{i=1}^m,\, (R^{(i)}(x^{(i)}))_{i=1}^m \bigr)$ is distributed exactly as the product of the distributions $\mu_{L^{(i)},\,R^{(i)}}$ for $i = 1, 2, \dots, m$.
1266	\end{proof}
1267	
1268	% Formalization-support nodes.  The five statements below are not results of the source
1269	% article; each isolates one register-bookkeeping step of the Lean proofs of the lemmas
1270	% above, and is recorded here so that those proofs remain traceable.
1271	\begin{lemma}[Formalization support for restriction to a subregister]\label{lem:cl-restriction-idem}
1272		\lean{MIPStarRE.QPBT.coordinateRestriction_coordinateRestriction}
1273		\leanok
1274		\uses{def:register-subspace}
1275		This is not a named statement of the source article; it isolates a step used in the Lean proofs of Lemma~\ref{lem:cl-kth} and Lemma~\ref{lem:cl-func-prod}. Let $S$ and $S'$ be register subspaces of $V$ with $S \subseteq S'$. Then $(x^{S'})^S = x^S$ for every $x \in V$.
1276	\end{lemma}
1277	\begin{proof}
1278		\leanok
1279		The two sides agree coordinatewise: a coordinate of $S$ is retained by both restrictions, since $S \subseteq S'$, and a coordinate outside $S$ is set to zero by both.
1280	\end{proof}
1281	
1282	\begin{lemma}[Formalization support for restricting a sum to one register]\label{lem:cl-restriction-sum}
1283		\lean{MIPStarRE.QPBT.coordinateRestriction_sum_eq}
1284		\leanok
1285		\uses{def:register-subspace}
1286		This is not a named statement of the source article; it isolates a step used in the Lean proofs of Lemma~\ref{lem:cl-func-prod} and Lemma~\ref{lem:cl-dist-prod}. Let $V^{(1)}, \dots, V^{(m)}$ be pairwise disjoint register subspaces of $V$ and, for each $j$, let $f_j \in V$ vanish outside $V^{(j)}$. Then $\bigl( \sum_{i=1}^m f_i \bigr)^{V^{(j)}} = f_j$ for every $j$.
1287	\end{lemma}
1288	\begin{proof}
1289		\leanok
1290		On a coordinate of $V^{(j)}$ every summand $f_i$ with $i \neq j$ vanishes, by disjointness, so the sum agrees there with $f_j$; outside $V^{(j)}$ both sides vanish.
1291	\end{proof}
1292	
1293	\begin{lemma}[Formalization support for the values of a supported CL function]\label{lem:cl-supported-vanishing}
1294		\lean{MIPStarRE.QPBT.CondLinearTerm.eval_eq_zero_of_not_mem}
1295		\leanok
1296		\uses{def:cl-func, def:register-subspace}
1297		This is not a named statement of the source article; it isolates a step used in the Lean proof of Lemma~\ref{lem:cl-dist-prod}. Let $S$ be a register subspace of $V$ and let $L$ be a CL function on $V$ all of whose factor spaces are contained in $S$. Then $L(x) \in S$ for every $x \in V$.
1298	\end{lemma}
1299	\begin{proof}
1300		\leanok
1301		\uses{def:cl-func}
1302		Induction on the level of $L$. The $0$-level function is the zero function. At level $\ell \ge 1$ we have $L(x) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{V_{>1}})$, where the first summand lies in $V_1 \subseteq S$ and the second lies in $S$ by the induction hypothesis, the factor spaces of $L_{>1,\,x^{L_1}}$ being contained in $S$ as well.
1303	\end{proof}
1304	
1305	\begin{lemma}[Formalization support for the arguments of a supported CL function]\label{lem:cl-supported-restriction}
1306		\lean{MIPStarRE.QPBT.CondLinearTerm.eval_coordinateRestriction}
1307		\leanok
1308		\uses{def:cl-func, def:register-subspace}
1309		This is not a named statement of the source article; it isolates a step used in the Lean proofs of Lemma~\ref{lem:cl-func-prod} and Lemma~\ref{lem:cl-dist-prod}. Let $S$ be a register subspace of $V$ and let $L$ be a CL function on $V$ all of whose factor spaces are contained in $S$. Then $L(x^S) = L(x)$ for every $x \in V$.
1310	\end{lemma}
1311	\begin{proof}
1312		\leanok
1313		\uses{def:cl-func}
1314		Induction on the level of $L$: the value of $L$ depends on $x$ only through the projections of $x$ onto the factor spaces of $L$, and $x^S$ and $x$ have the same projection onto every register subspace contained in $S$.
1315	\end{proof}
1316	
1317	\begin{lemma}[Formalization support for equal-level direct sums]\label{lem:cl-func-prod-same-level}
1318		\lean{MIPStarRE.QPBT.IsCondLinearOn.directSum_sameLevel}
1319		\leanok
1320		\uses{def:cl-func, def:register-subspace}
1321		This is not a named statement of the source article; it is the equal-level case of Lemma~\ref{lem:cl-func-prod}, isolated because the Lean proof of that lemma first raises every level $\ell_j$ to $\ell = \max_j \ell_j$. Let $V^{(1)}, \dots, V^{(m)}$ be pairwise disjoint register subspaces of $V$ and, for each $j$, let $L^{(j)}$ be an $\ell$-level CL function on $V^{(j)}$. Then the function $x \mapsto \sum_{j=1}^m L^{(j)}(x^{V^{(j)}})$ is an $\ell$-level CL function on $\bigoplus_{j=1}^m V^{(j)}$.
1322	\end{lemma}
1323	\begin{proof}
1324		\leanok
1325		\uses{def:cl-func, lem:cl-restriction-idem, lem:cl-restriction-sum, lem:cl-supported-restriction}
1326		Induction on $\ell$, as in the proof of Lemma~\ref{lem:cl-func-prod}: at level $0$ every summand is the zero function, and at level $\ell \ge 1$ the first-level linear maps combine to a linear map on $\bigoplus_j V^{(j)}_1$ while, for each prefix value, the remainders combine to an $(\ell-1)$-level CL function by the induction hypothesis. Identifying the restriction of the common input to each register $V^{(j)}$ with the input of the $j$-th summand uses Lemma~\ref{lem:cl-restriction-idem}, Lemma~\ref{lem:cl-restriction-sum}, and Lemma~\ref{lem:cl-supported-restriction}.
1327	\end{proof}
